import { ApprovalToken, ApprovalCache } from './types';

export class ApprovalService {
  private cache: Map<string, { token: ApprovalToken, expiresAt: number }>

  constructor() {
    this.cache = new Map();
  }

  async verifyToken(token: string): Promise<boolean> {
    if (this.cache.has(token)) {
      const cachedToken = this.cache.get(token);
      if (cachedToken && cachedToken.expiresAt > Date.now()) {
        return true;
      }
    }
    // Token not found or expired, verify normally
    const isValid = await this.normalVerification(token);
    if (isValid) {
      this.cache.set(token, { token, expiresAt: Date.now() + 3600000 }); // Cache for 1 hour
    }
    return isValid;
  }

  private async normalVerification(token: string): Promise<boolean> {
    // Simulate normal verification logic
    return new Promise(resolve => setTimeout(() => resolve(token === 'validToken'), 1000));
  }
}

import { writeFile } from 'fs/promises';
import { promisify } from 'util';

const writeFileAsync = promisify(writeFile);

export async function writeFileWithSizeCheck(content: string, filePath: string): Promise<void> {
  const maxFileSize = 1024 * 1024; // 1MB
  const buffer = Buffer.from(content);
  if (buffer.length > maxFileSize) {
    throw new Error(`File size exceeds maximum allowed size (1MB). Actual size: ${buffer.length} bytes`);
  }
  await writeFileAsync(filePath, content);
}

