import { escapeRegExp } from 'lodash';

export function grep(query: string, fileContent: string): string[] {
  // Sanitize the input query to prevent command injection
  const sanitizedQuery = escapeRegExp(query);
  const regex = new RegExp(sanitizedQuery, 'g');
  const matches = fileContent.match(regex);
  return matches ? matches.map(match => match.trim()) : [];
}

import { Step } from './types';

export class Loop {
  private retryCount: number = 0;

  async executeStep(step: Step): Promise<void> {
    while (this.retryCount < 5) {
      try {
        await step.execute();
        this.retryCount = 0; // Reset retry count on success
        break;
      } catch (error) {
        this.retryCount++;
        console.error(`Step failed, retrying... (Attempt ${this.retryCount})`);
      }
    }
    if (this.retryCount === 5) {
      throw new Error(`Step failed after 5 retries`);
    }
  }
}

import { Step } from './types';

export class Loop {
  private retryCounts: Map<Step, number> = new Map();

  async executeStep(step: Step): Promise<void> {
    let currentRetryCount = this.retryCounts.get(step) || 0;
    while (currentRetryCount < 5) {
      try {
        await step.execute();
        this.retryCounts.set(step, 0); // Reset retry count on success
        break;
      } catch (error) {
        currentRetryCount++;
        this.retryCounts.set(step, currentRetryCount);
        console.error(`Step failed, retrying... (Attempt ${currentRetryCount})`);
      }
    }
    if (currentRetryCount === 5) {
      throw new Error(`Step failed after 5 retries`);
    }
  }
}

